/* modeles.js — les modèles 3D « style PS1 » du bodega.

   Chaque modèle est le fichier .glb livré par l'atelier « Modèle 3D style PS1 », embarqué tel quel en base64
   et lu par le petit lecteur glTF ci-dessous : géométrie indexée, UV, couleurs de sommets (l'éclairage est cuit
   dedans) et atlas PNG. Les matériaux sont « unlit » : MeshBasicMaterial, texture au plus proche voisin.

   MODELES.creer(THREE, nom, options) → THREE.Group, dans le repère du modèle (mètres, Y vers le haut).
     Le groupe est rendu tout de suite, vide ; ses pièces y arrivent dès que l'atlas est décodé.
     Chaque nœud glTF devient un THREE.Group qui porte son nom.
     options.teinte : [r, v, b] multiplié aux couleurs du modèle, pour l'accorder à la lumière de la pièce
     options.pret   : function (groupe), appelée quand le modèle est complet
   MODELES.trouver(groupe, nom) → le nœud de ce nom, ou null
   MODELES.noms() → les modèles disponibles
*/
(function () {
  'use strict';

  var GLB = {
    // Tireuse de bodega : nœuds « tireuse », « poteau_cuivre », « photophores ».
    // Origine au pied de la colonne, sur le comptoir ; +Z côté client. 1 214 triangles, atlas 128 × 128.
    tireuse: '',
    // Bouteille de bière Popihn : un seul nœud, « bouteille ». Origine au centre du cul de la bouteille ; 23 cm de haut,
    // 5,9 cm de diamètre. Atlas 128 × 128.
    bouteille: ''
  };

  var TYPES = { 5120: Int8Array, 5121: Uint8Array, 5122: Int16Array, 5123: Uint16Array, 5125: Uint32Array, 5126: Float32Array };
  var TAILLE = { SCALAR: 1, VEC2: 2, VEC3: 3, VEC4: 4 };
  var lus = {};

  function octets(b64) {
    var s = atob(b64), n = s.length, a = new Uint8Array(n), i;
    for (i = 0; i < n; i++) a[i] = s.charCodeAt(i);
    return a;
  }
  function texte(bytes) {
    var s = '', i;
    for (i = 0; i < bytes.length; i += 8192) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 8192));
    return s;
  }

  // Un .glb : 12 octets d'en-tête, un bloc JSON, un bloc binaire
  function lire(nom) {
    if (lus[nom]) return lus[nom];
    var bytes = octets(GLB[nom]), dv = new DataView(bytes.buffer);
    if (dv.getUint32(0, true) !== 0x46546C67) throw new Error('modeles.js : « ' + nom + ' » n\'est pas un .glb');
    var nJson = dv.getUint32(12, true), brut = bytes.subarray(20, 20 + nJson), bin = 20 + nJson + 8;
    var json = JSON.parse(typeof TextDecoder !== 'undefined' ? new TextDecoder().decode(brut) : texte(brut));
    function acces(i) {
      var a = json.accessors[i], v = json.bufferViews[a.bufferView], T = TYPES[a.componentType], n = a.count * TAILLE[a.type];
      var d = bin + (v.byteOffset || 0) + (a.byteOffset || 0);
      if (v.byteStride && v.byteStride !== TAILLE[a.type] * T.BYTES_PER_ELEMENT) throw new Error('modeles.js : tampons entrelacés non gérés');
      return { t: new T(bytes.buffer.slice(d, d + n * T.BYTES_PER_ELEMENT)), n: TAILLE[a.type], type: a.componentType };
    }
    var im = json.images[0], vi = json.bufferViews[im.bufferView];
    var png = 'data:' + (im.mimeType || 'image/png') + ';base64,' + btoa(texte(bytes.subarray(bin + (vi.byteOffset || 0), bin + (vi.byteOffset || 0) + vi.byteLength)));
    lus[nom] = { json: json, acces: acces, png: png };
    return lus[nom];
  }

  function geometrie(THREE, m, p) {
    var g = new THREE.BufferGeometry(), pos = m.acces(p.attributes.POSITION), uv, col, c, k, i, n;
    g.setAttribute('position', new THREE.BufferAttribute(pos.t, 3));
    if (p.attributes.TEXCOORD_0 !== undefined) {                 // glTF compte V depuis le haut de l'image, three.js depuis le bas
      uv = m.acces(p.attributes.TEXCOORD_0).t;
      for (i = 1; i < uv.length; i += 2) uv[i] = 1 - uv[i];
      g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    }
    if (p.attributes.COLOR_0 !== undefined) {
      col = m.acces(p.attributes.COLOR_0); n = col.t.length / col.n; c = new Float32Array(n * 3);
      k = col.type === 5121 ? 1 / 255 : col.type === 5123 ? 1 / 65535 : 1;
      for (i = 0; i < n; i++) { c[i * 3] = col.t[i * col.n] * k; c[i * 3 + 1] = col.t[i * col.n + 1] * k; c[i * 3 + 2] = col.t[i * col.n + 2] * k; }
      g.setAttribute('color', new THREE.BufferAttribute(c, 3));
    }
    if (p.indices !== undefined) g.setIndex(new THREE.BufferAttribute(m.acces(p.indices).t, 1));
    return g;
  }

  function construire(THREE, m, racine, img, opts) {
    var cv = document.createElement('canvas'), tex, mats, json = m.json, t = opts.teinte || [1, 1, 1];
    cv.width = img.naturalWidth || img.width; cv.height = img.naturalHeight || img.height;
    cv.getContext('2d').drawImage(img, 0, 0);
    tex = new THREE.CanvasTexture(cv);
    tex.magFilter = THREE.NearestFilter; tex.minFilter = THREE.NearestFilter; tex.generateMipmaps = false;
    mats = (json.materials || [{}]).map(function (d) {
      var f = (d.pbrMetallicRoughness || {}).baseColorFactor || [1, 1, 1, 1], o = { map: tex, vertexColors: true }, mat;
      if (d.alphaMode === 'BLEND') { o.transparent = true; o.opacity = f[3]; o.depthWrite = false; }
      if (d.doubleSided) o.side = THREE.DoubleSide;
      mat = new THREE.MeshBasicMaterial(o);
      mat.color.setRGB(f[0] * t[0], f[1] * t[1], f[2] * t[2]);
      return mat;
    });
    function noeud(i) {
      var d = json.nodes[i], g = new THREE.Group();
      g.name = d.name || '';
      if (d.translation) g.position.set(d.translation[0], d.translation[1], d.translation[2]);
      if (d.rotation) g.quaternion.set(d.rotation[0], d.rotation[1], d.rotation[2], d.rotation[3]);
      if (d.scale) g.scale.set(d.scale[0], d.scale[1], d.scale[2]);
      if (d.mesh !== undefined) json.meshes[d.mesh].primitives.forEach(function (p) {
        var me = new THREE.Mesh(geometrie(THREE, m, p), mats[p.material || 0]);
        if (me.material.transparent) me.renderOrder = 1;         // le verre après le reste
        g.add(me);
      });
      (d.children || []).forEach(function (k) { g.add(noeud(k)); });
      return g;
    }
    json.scenes[json.scene || 0].nodes.forEach(function (i) { racine.add(noeud(i)); });
  }

  function creer(THREE, nom, opts) {
    opts = opts || {};
    var racine = new THREE.Group(), m, img;
    racine.name = nom;
    try {
      if (!GLB[nom]) throw new Error('modeles.js : modèle inconnu « ' + nom + ' »');
      m = lire(nom);
      img = new Image();
      img.onload = function () {
        try { construire(THREE, m, racine, img, opts); if (opts.pret) opts.pret(racine); }
        catch (e) { if (window.console) console.warn(e); }
      };
      img.onerror = function () {                                // atlas illisible : le modèle reste visible, en laiton uni
        var cv = document.createElement('canvas'), g;
        cv.width = cv.height = 2; g = cv.getContext('2d'); g.fillStyle = '#c69a3c'; g.fillRect(0, 0, 2, 2);
        try { construire(THREE, m, racine, cv, opts); if (opts.pret) opts.pret(racine); }
        catch (e) { if (window.console) console.warn(e); }
      };
      img.src = m.png;
    } catch (e) { if (window.console) console.warn(e); }
    return racine;
  }

  function trouver(g, nom) {
    var i, r;
    if (!g) return null;
    if (g.name === nom) return g;
    for (i = 0; g.children && i < g.children.length; i++) { r = trouver(g.children[i], nom); if (r) return r; }
    return null;
  }

  window.MODELES = { creer: creer, trouver: trouver, noms: function () { return Object.keys(GLB); } };
})();
